-- Name: notify_attendance_confirmed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_attendance_confirmed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_event_name text;
BEGIN
    SELECT name INTO v_event_name FROM public.events WHERE id = NEW.event_id;
    PERFORM public.insert_notification(
        NEW.user_id,
        'attendance_confirmed',
        'Asistencia confirmada',
        COALESCE(v_event_name, 'Tu asistencia fue confirmada'),
        jsonb_build_object('eventId', NEW.event_id)
    );
    RETURN NEW;
END;
$$;


--

-- Name: notify_event_cancelled(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_event_cancelled() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_recipient uuid;
BEGIN
    IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
        RETURN NEW;
    END IF;
    FOR v_recipient IN
        SELECT user_id FROM public.event_invites
        WHERE event_id = NEW.id AND status <> 'declined'
    LOOP
        PERFORM public.insert_notification(
            v_recipient,
            'event_cancelled',
            'Evento cancelado',
            NEW.name,
            jsonb_build_object('eventId', NEW.id)
        );
    END LOOP;
    RETURN NEW;
END;
$$;


